EXPANDED_V4["sets"] = {
    "Python": "# Set\ns = {1, 2, 3}\ns.add(4)\ns.discard(2)\n\n# Operations\na = {1, 2, 3, 4}\nb = {3, 4, 5, 6}\na | b  # Union: {1,2,3,4,5,6}\na & b  # Intersection: {3,4}\na - b  # Difference: {1,2}\na ^ b  # Symmetric diff: {1,2,5,6}\na <= b  # Subset: False\na >= b  # Superset: False\n\n# Frozen set (immutable, hashable)\nfs = frozenset([1, 2, 3])\n\n# Comprehension\nevens = {x for x in range(20) if x % 2 == 0}\n\n# Membership\n3 in s  # True",
    "JavaScript": "const s = new Set([1, 2, 3]);\ns.add(4);\ns.delete(2);\ns.has(3);  // true\ns.size;  // 3\n\n// Iteration\nfor (const val of s) console.log(val);\n[...s].map(x => x * 2);\n\n// Set operations (ES2025)\n// s.union(other)\n// s.intersection(other)\n// s.difference(other)\n\n// Manual operations\nconst a = new Set([1,2,3,4]);\nconst b = new Set([3,4,5,6]);\nconst union = new Set([...a, ...b]);\nconst inter = new Set([...a].filter(x => b.has(x)));\nconst diff = new Set([...a].filter(x => !b.has(x)));",
    "Go": "// Go has no built-in Set — use map[T]struct{}\ntype Set[T comparable] map[T]struct{}\n\nfunc NewSet[T comparable](items ...T) Set[T] {\n    s := Set[T]{}\n    for _, item := range items {\n        s[item] = struct{}{}\n    }\n    return s\n}\n\nfunc (s Set[T]) Add(item T) { s[item] = struct{}{} }\nfunc (s Set[T]) Has(item T) bool { _, ok := s[item]; return ok }\nfunc (s Set[T]) Remove(item T) { delete(s, item) }\n\ns := NewSet(1, 2, 3)\ns.Add(4)\ns.Has(3)  // true",
    "Rust": "use std::collections::HashSet;\n\nlet mut s: HashSet<i32> = HashSet::from([1, 2, 3]);\ns.insert(4);\ns.remove(&2);\ns.contains(&3);  // true\ns.len();  // 3\n\n// Operations\nlet a: HashSet<i32> = [1,2,3,4].into();\nlet b: HashSet<i32> = [3,4,5,6].into();\nlet union: HashSet<_> = a.union(&b).collect();\nlet inter: HashSet<_> = a.intersection(&b).collect();\nlet diff: HashSet<_> = a.difference(&b).collect();\nlet sym_diff: HashSet<_> = a.symmetric_difference(&b).collect();\na.is_subset(&b);",
    "Java": "Set<Integer> s = new HashSet<>(Set.of(1, 2, 3));\ns.add(4);\ns.remove(2);\ns.contains(3);  // true\ns.size();  // 3\n\n// Operations\nSet<Integer> a = new HashSet<>(Set.of(1,2,3,4));\nSet<Integer> b = new HashSet<>(Set.of(3,4,5,6));\n\nSet<Integer> union = new HashSet<>(a);\nunion.addAll(b);  // {1,2,3,4,5,6}\n\nSet<Integer> inter = new HashSet<>(a);\ninter.retainAll(b);  // {3,4}\n\nSet<Integer> diff = new HashSet<>(a);\ndiff.removeAll(b);  // {1,2}\n\n// Immutable\nvar immutable = Set.of(1, 2, 3);\n\n// TreeSet (sorted)\nTreeSet<Integer> sorted = new TreeSet<>(s);",
    "C#": "var s = new HashSet<int> {1, 2, 3};\ns.Add(4);\ns.Remove(2);\ns.Contains(3);  // true\n\n// Operations\nvar a = new HashSet<int> {1,2,3,4};\nvar b = new HashSet<int> {3,4,5,6};\n\na.UnionWith(b);  // Mutates a\na.IntersectWith(b);\na.ExceptWith(b);\na.SymmetricExceptWith(b);\na.IsSubsetOf(b);\n\n// LINQ\nvar union = a.Union(b).ToHashSet();\nvar inter = a.Intersect(b).ToHashSet();",
    "Swift": "var s: Set = [1, 2, 3]\ns.insert(4)\ns.remove(2)\ns.contains(3)  // true\n\n// Operations\nlet a: Set = [1, 2, 3, 4]\nlet b: Set = [3, 4, 5, 6]\na.union(b)  // {1,2,3,4,5,6}\na.intersection(b)  // {3,4}\na.subtracting(b)  // {1,2}\na.symmetricDifference(b)  // {1,2,5,6}\na.isSubset(of: b)  // false",
    "Kotlin": "val s = mutableSetOf(1, 2, 3)\ns.add(4)\ns.remove(2)\ns.contains(3)  // true\n\n// Operations\nval a = setOf(1, 2, 3, 4)\nval b = setOf(3, 4, 5, 6)\na union b  // {1,2,3,4,5,6}\na intersect b  // {3,4}\na subtract b  // {1,2}\n\n// Sorted\nval sorted = sortedSetOf(3, 1, 4, 1, 5)",
    "Ruby": "require 'set'\ns = Set.new([1, 2, 3])\ns.add(4)\ns.delete(2)\ns.include?(3)  # true\n\na = Set.new([1,2,3,4])\nb = Set.new([3,4,5,6])\na | b  # Union\na & b  # Intersection\na - b  # Difference\na ^ b  # Symmetric diff\na.subset?(b)  # false",
    "Haskell": "import qualified Data.Set as Set\n\nlet s = Set.fromList [1, 2, 3]\nlet s2 = Set.insert 4 s\nlet s3 = Set.delete 2 s\nSet.member 3 s  -- True\n\nlet a = Set.fromList [1,2,3,4]\nlet b = Set.fromList [3,4,5,6]\nSet.union a b\nSet.intersection a b\nSet.difference a b\nSet.isSubsetOf a b",
    "PHP": "// SplObjectStorage or arrays as sets\n$s = [1, 2, 3];\n$s = array_unique(array_merge($s, [4]));\nin_array(3, $s);  // true\n\n// Operations\n$a = [1,2,3,4];\n$b = [3,4,5,6];\narray_unique(array_merge($a, $b));  // Union\narray_intersect($a, $b);  // [3,4]\narray_diff($a, $b);  // [1,2]",
    "Scala": "val s = Set(1, 2, 3)\nval s2 = s + 4\nval s3 = s - 2\ns.contains(3)  // true\n\nval a = Set(1,2,3,4)\nval b = Set(3,4,5,6)\na union b\na intersect b\na diff b\na subsetOf b",
    "Elixir": "s = MapSet.new([1, 2, 3])\ns = MapSet.put(s, 4)\ns = MapSet.delete(s, 2)\nMapSet.member?(s, 3)  # true\n\na = MapSet.new([1,2,3,4])\nb = MapSet.new([3,4,5,6])\nMapSet.union(a, b)\nMapSet.intersection(a, b)\nMapSet.difference(a, b)\nMapSet.subset?(a, b)",
    "Clojure": "(def s #{1 2 3})\n(conj s 4)  ;; #{1 2 3 4}\n(disj s 2)  ;; #{1 3}\n(contains? s 3)  ;; true\n\n(require '[clojure.set :as set])\n(set/union #{1 2 3} #{3 4 5})\n(set/intersection #{1 2 3} #{2 3 4})\n(set/difference #{1 2 3} #{2 3})\n(set/subset? #{1 2} #{1 2 3})",
    "Dart": "final s = {1, 2, 3};\ns.add(4);\ns.remove(2);\ns.contains(3);  // true\n\nfinal a = {1, 2, 3, 4};\nfinal b = {3, 4, 5, 6};\na.union(b);\na.intersection(b);\na.difference(b);",
    "Julia": "s = Set([1, 2, 3])\npush!(s, 4)\ndelete!(s, 2)\n3 in s  # true\n\na = Set([1,2,3,4])\nb = Set([3,4,5,6])\nunion(a, b)\nintersect(a, b)\nsetdiff(a, b)\nissubset(a, b)",
    "Lua": "-- Lua has no built-in set; use tables\nlocal s = {}\ns[1] = true; s[2] = true; s[3] = true\ns[4] = true  -- add\ns[2] = nil  -- remove\nif s[3] then print('has 3') end",
    "Nim": "import std/sets\nvar s = toHashSet([1, 2, 3])\ns.incl(4)\ns.excl(2)\n3 in s  # true\n\nlet a = toHashSet([1,2,3,4])\nlet b = toHashSet([3,4,5,6])\na + b  # union\na * b  # intersection\na - b  # difference",
    "Crystal": "s = Set{1, 2, 3}\ns.add(4)\ns.delete(2)\ns.includes?(3)  # true\n\na = Set{1, 2, 3, 4}\nb = Set{3, 4, 5, 6}\na | b  # Union\na & b  # Intersection\na - b  # Difference",
    "OCaml": "module ISet = Set.Make(Int)\n\nlet s = ISet.of_list [1; 2; 3]\nlet s2 = ISet.add 4 s\nlet s3 = ISet.remove 2 s\nISet.mem 3 s  (* true *)\n\nISet.union s (ISet.of_list [4; 5])\nISet.inter s (ISet.of_list [2; 3; 4])\nISet.diff s (ISet.of_list [2; 3])",
    "F#": "let s = Set.ofList [1; 2; 3]\nlet s2 = s |> Set.add 4\nlet s3 = s |> Set.remove 2\nSet.contains 3 s  // true\n\nSet.union s (Set.ofList [4; 5])\nSet.intersect s (Set.ofList [2; 3; 4])\nSet.difference s (Set.ofList [2; 3])\nSet.isSubset s (Set.ofList [1;2;3;4])",
    "Erlang": "S = sets:from_list([1, 2, 3]),\nS2 = sets:add_element(4, S),\nS3 = sets:del_element(2, S),\nsets:is_element(3, S),  %% true\n\nA = sets:from_list([1,2,3,4]),\nB = sets:from_list([3,4,5,6]),\nsets:union(A, B),\nsets:intersection(A, B),\nsets:subtract(A, B).",
    "Zig": "// Zig std doesn't have a Set type\n// Use AutoHashMap(T, void)\nvar set = std.AutoHashMap(i32, void).init(allocator);\ntry set.put(1, {});\ntry set.put(2, {});\ntry set.put(3, {});\n_ = set.contains(3);",
    "Racket": "(define s (set 1 2 3))\n(set-add s 4)\n(set-remove s 2)\n(set-member? s 3)  ;; true\n\n(set-union (set 1 2 3) (set 3 4 5))\n(set-intersect (set 1 2 3) (set 2 3 4))\n(set-subtract (set 1 2 3) (set 2 3))\n(subset? (set 1 2) (set 1 2 3))",
    "D": "import std.container.rbtree;\n\nauto s = redBlackTree!int(1, 2, 3);\ns.insert(4);\ns.removeKey(2);\n3 in s;  // true",
    "Perl": "# Hash keys as set\nmy %s;\n@s{1, 2, 3} = ();\n$s{4} = undef;  # add\ndelete $s{2};  # remove\nexists $s{3};  # true",
    "R": "s <- c(1, 2, 3)\na <- c(1, 2, 3, 4)\nb <- c(3, 4, 5, 6)\nunion(a, b)\nintersect(a, b)\nsetdiff(a, b)\nis.element(3, s)  # TRUE",
    "C": "// C has no built-in set\n// Use bit arrays for small integers\nunsigned int set = 0;\nset |= (1 << 3);  // Add 3\nset &= ~(1 << 2);  // Remove 2\nif (set & (1 << 3)) printf(\"has 3\\n\");\n\n// Union, intersection, difference\nunsigned int a = 0x0F, b = 0xF0;\nunsigned int u = a | b;  // union\nunsigned int i = a & b;  // intersection\nunsigned int d = a & ~b; // difference",
    "C++": "#include <unordered_set>\n#include <set>\n\nstd::unordered_set<int> s = {1, 2, 3};\ns.insert(4);\ns.erase(2);\ns.count(3);  // 1\ns.contains(3);  // C++20\n\n// Ordered set\nstd::set<int> ordered = {3, 1, 4, 1, 5};\n// Automatically sorted & unique: {1, 3, 4, 5}\n\n// Algorithms\nstd::set<int> a = {1,2,3,4};\nstd::set<int> b = {3,4,5,6};\nstd::set<int> u;\nstd::set_union(a.begin(), a.end(), b.begin(), b.end(),\n    std::inserter(u, u.begin()));",
    "TypeScript": "const s = new Set<number>([1, 2, 3]);\ns.add(4);\ns.delete(2);\ns.has(3);  // true\ns.size;  // 3\n\n// Typed operations\nfunction union<T>(a: Set<T>, b: Set<T>): Set<T> {\n  return new Set([...a, ...b]);\n}\nfunction intersection<T>(a: Set<T>, b: Set<T>): Set<T> {\n  return new Set([...a].filter(x => b.has(x)));\n}\nfunction difference<T>(a: Set<T>, b: Set<T>): Set<T> {\n  return new Set([...a].filter(x => !b.has(x)));\n}",
    "JavaScript": "const s = new Set([1, 2, 3]);\ns.add(4);\ns.delete(2);\ns.has(3);  // true\n\n// Iteration\nfor (const val of s) console.log(val);\n\n// Convert\n[...s];\nArray.from(s);\n\n// Operations\nconst a = new Set([1,2,3,4]);\nconst b = new Set([3,4,5,6]);\nconst union = new Set([...a, ...b]);\nconst inter = new Set([...a].filter(x => b.has(x)));\nconst diff = new Set([...a].filter(x => !b.has(x)));",
}

EXPANDED_V4["list_comprehensions"] = {
    "Python": "# List comprehension\nsquares = [x**2 for x in range(10)]\nevens = [x for x in range(20) if x % 2 == 0]\npairs = [(x, y) for x in range(3) for y in range(3)]\nflat = [item for sublist in nested for item in sublist]\n\n# Dict comprehension\nsquare_map = {x: x**2 for x in range(5)}\nfiltered = {k: v for k, v in d.items() if v > 0}\n\n# Set comprehension\nunique = {word.lower() for word in words}\n\n# Generator expression (lazy)\ngen = (x**2 for x in range(1000000))\nsum(x**2 for x in range(100))\n\n# Nested\nmatrix = [[1,2,3],[4,5,6]]\ntransposed = [[row[i] for row in matrix] for i in range(3)]\n\n# Walrus operator in comprehension\nresults = [y for x in data if (y := expensive(x)) > 0]",
    "JavaScript": "// Array.from + map/filter\nconst squares = Array.from({length: 10}, (_, i) => i * i);\nconst evens = [...Array(20).keys()].filter(x => x % 2 === 0);\n\n// map + filter chain\nconst result = [1,2,3,4,5]\n  .filter(x => x % 2 === 0)\n  .map(x => x * x);\n\n// flatMap\nconst flat = [[1,2], [3,4]].flatMap(x => x);\nconst pairs = [1,2,3].flatMap(x => [1,2,3].map(y => [x, y]));\n\n// Array.from range\nconst range = (n) => Array.from({length: n}, (_, i) => i);",
    "Haskell": "-- List comprehension\nsquares = [x^2 | x <- [0..9]]\nevens = [x | x <- [0..19], even x]\npairs = [(x, y) | x <- [0..2], y <- [0..2]]\n\n-- Guards\nfizzBuzz = [show x | x <- [1..100], x `mod` 15 == 0]\n\n-- Pattern matching in comprehensions\nfirsts = [x | (x, _) <- pairs]\n\n-- Nested\nflat = [x | xs <- nested, x <- xs]\n\n-- Parallel list comprehension (GHC extension)\n-- [x + y | x <- [1,2,3] | y <- [10,20,30]]",
    "Scala": "// For comprehension\nval squares = for (x <- 0 until 10) yield x * x\nval evens = for (x <- 0 until 20 if x % 2 == 0) yield x\nval pairs = for (x <- 0 until 3; y <- 0 until 3) yield (x, y)\n\n// Nested with guard\nval result = for {\n  x <- List(1, 2, 3)\n  y <- List(4, 5, 6)\n  if (x + y) % 2 == 0\n} yield (x, y)\n\n// flatMap equivalent\nList(1,2,3).flatMap(x => List(4,5,6).map(y => (x, y)))",
    "Elixir": "# For comprehension\nsquares = for x <- 0..9, do: x * x\nevens = for x <- 0..19, rem(x, 2) == 0, do: x\npairs = for x <- 0..2, y <- 0..2, do: {x, y}\n\n# With filter\nresult = for x <- 1..100, rem(x, 3) == 0, do: x\n\n# Into different types\nmap = for {k, v} <- list, into: %{}, do: {k, v}\nset = for x <- list, uniq: true, into: MapSet.new(), do: x",
    "Clojure": ";; for comprehension\n(for [x (range 10)] (* x x))\n(for [x (range 20) :when (even? x)] x)\n(for [x (range 3) y (range 3)] [x y])\n\n;; with let binding\n(for [x (range 10)\n      :let [sq (* x x)]\n      :when (> sq 20)]\n  sq)\n\n;; Equivalent with map/filter\n(->> (range 10)\n     (map #(* % %))\n     (filter #(> % 20)))",
    "Ruby": "# map + select\nsquares = (0...10).map { |x| x ** 2 }\nevens = (0...20).select(&:even?)\npairs = (0...3).flat_map { |x| (0...3).map { |y| [x, y] } }\n\n# One-liner\nresult = [1,2,3,4,5].select(&:even?).map { |x| x ** 2 }\n\n# collect (alias for map)\n[1,2,3].collect { |x| x * 2 }",
    "C#": "// LINQ query syntax\nvar squares = from x in Enumerable.Range(0, 10) select x * x;\nvar evens = from x in Enumerable.Range(0, 20) where x % 2 == 0 select x;\nvar pairs = from x in Enumerable.Range(0, 3)\n            from y in Enumerable.Range(0, 3)\n            select (x, y);\n\n// Method syntax\nvar result = Enumerable.Range(0, 10)\n    .Where(x => x % 2 == 0)\n    .Select(x => x * x)\n    .ToList();",
    "Kotlin": "// No dedicated syntax — use functional chains\nval squares = (0 until 10).map { it * it }\nval evens = (0 until 20).filter { it % 2 == 0 }\nval pairs = (0 until 3).flatMap { x -> (0 until 3).map { y -> x to y } }\n\n// buildList\nval result = buildList {\n    for (x in 0 until 10) {\n        if (x % 2 == 0) add(x * x)\n    }\n}",
    "Rust": "// No built-in comprehension — use iterators\nlet squares: Vec<i32> = (0..10).map(|x| x * x).collect();\nlet evens: Vec<i32> = (0..20).filter(|x| x % 2 == 0).collect();\n\n// flat_map for nested\nlet pairs: Vec<(i32,i32)> = (0..3)\n    .flat_map(|x| (0..3).map(move |y| (x, y)))\n    .collect();\n\n// Macro crate: cute\n// let squares = c![x*x, for x in 0..10];",
    "Go": "// No comprehension syntax — use loops\nsquares := make([]int, 10)\nfor i := 0; i < 10; i++ {\n    squares[i] = i * i\n}\n\n// Filter pattern\nvar evens []int\nfor _, x := range nums {\n    if x%2 == 0 {\n        evens = append(evens, x)\n    }\n}",
    "Swift": "let squares = (0..<10).map { $0 * $0 }\nlet evens = (0..<20).filter { $0 % 2 == 0 }\nlet pairs = (0..<3).flatMap { x in (0..<3).map { y in (x, y) } }\n\n// compactMap (filter nil)\nlet ints = [\"1\", \"abc\", \"3\"].compactMap { Int($0) }",
    "Java": "// Stream API\nvar squares = IntStream.range(0, 10).map(x -> x * x).boxed().toList();\nvar evens = IntStream.range(0, 20).filter(x -> x % 2 == 0).boxed().toList();\nvar pairs = IntStream.range(0, 3)\n    .boxed()\n    .flatMap(x -> IntStream.range(0, 3).mapToObj(y -> List.of(x, y)))\n    .toList();",
    "Julia": "# Array comprehension\nsquares = [x^2 for x in 0:9]\nevens = [x for x in 0:19 if iseven(x)]\npairs = [(x, y) for x in 0:2, y in 0:2]\n\n# Generator\ngen = (x^2 for x in 0:9)\nsum(x^2 for x in 0:99)\n\n# Dict comprehension\nDict(x => x^2 for x in 1:5)",
    "Dart": "final squares = [for (var i = 0; i < 10; i++) i * i];\nfinal evens = [for (var i = 0; i < 20; i++) if (i % 2 == 0) i];\n\n// Spread + collection-if/for\nfinal result = [\n  for (var x in [1,2,3,4,5])\n    if (x.isEven) x * x,\n];",
    "PHP": "$squares = array_map(fn($x) => $x ** 2, range(0, 9));\n$evens = array_filter(range(0, 19), fn($x) => $x % 2 === 0);",
    "Lua": "-- No comprehension; manual loops\nlocal squares = {}\nfor i = 0, 9 do squares[#squares+1] = i*i end\n\nlocal evens = {}\nfor i = 0, 19 do\n    if i % 2 == 0 then evens[#evens+1] = i end\nend",
    "Nim": "import sequtils, sugar\n\nlet squares = toSeq(0..9).mapIt(it * it)\nlet evens = toSeq(0..19).filterIt(it mod 2 == 0)\n\n# Comprehension sugar\nlet pairs = collect(newSeq):\n  for x in 0..2:\n    for y in 0..2:\n      (x, y)",
    "Crystal": "squares = (0...10).map { |x| x ** 2 }\nevens = (0...20).select(&.even?)\npairs = (0...3).flat_map { |x| (0...3).map { |y| {x, y} } }",
    "Erlang": "Squares = [X*X || X <- lists:seq(0, 9)].\nEvens = [X || X <- lists:seq(0, 19), X rem 2 =:= 0].\nPairs = [{X, Y} || X <- lists:seq(0, 2), Y <- lists:seq(0, 2)].",
    "F#": "let squares = [ for x in 0..9 -> x * x ]\nlet evens = [ for x in 0..19 do if x % 2 = 0 then yield x ]\nlet pairs = [ for x in 0..2 do for y in 0..2 do yield (x, y) ]\n\n// Sequence expression (lazy)\nlet gen = seq { for x in 0..9 -> x * x }",
    "OCaml": "(* List.init *)\nList.init 10 (fun x -> x * x)\nList.filter (fun x -> x mod 2 = 0) (List.init 20 Fun.id)\n\n(* Manual comprehension *)\nlet pairs =\n  List.concat_map (fun x ->\n    List.map (fun y -> (x, y)) [0;1;2]\n  ) [0;1;2]",
    "Racket": ";; for/list\n(for/list ([x (in-range 10)]) (* x x))\n(for/list ([x (in-range 20)] #:when (even? x)) x)\n(for*/list ([x (in-range 3)] [y (in-range 3)]) (list x y))\n\n;; for/fold\n(for/fold ([sum 0]) ([x (in-range 100)]) (+ sum (* x x)))",
    "D": "import std.range, std.algorithm;\n\nauto squares = iota(10).map!(x => x * x).array;\nauto evens = iota(20).filter!(x => x % 2 == 0).array;",
    "Perl": "my @squares = map { $_ ** 2 } 0..9;\nmy @evens = grep { $_ % 2 == 0 } 0..19;",
    "R": "squares <- sapply(0:9, function(x) x^2)\nevens <- Filter(function(x) x %% 2 == 0, 0:19)\n\n# Vectorized (idiomatic R)\nsquares <- (0:9)^2\nevens <- (0:19)[0:19 %% 2 == 0]",
    "C": "// No comprehension; use loops\nint squares[10];\nfor (int i = 0; i < 10; i++) squares[i] = i * i;",
    "C++": "// ranges (C++20)\n#include <ranges>\nauto squares = std::views::iota(0, 10)\n    | std::views::transform([](int x) { return x * x; });\n\nauto evens = std::views::iota(0, 20)\n    | std::views::filter([](int x) { return x % 2 == 0; });\n\n// Traditional\nstd::vector<int> sq;\nfor (int i = 0; i < 10; ++i) sq.push_back(i * i);",
    "TypeScript": "// No dedicated syntax\nconst squares = Array.from({length: 10}, (_, i) => i * i);\nconst evens: number[] = [...Array(20).keys()].filter(x => x % 2 === 0);\nconst pairs: [number, number][] = Array.from({length: 3}, (_, x) =>\n  Array.from({length: 3}, (_, y) => [x, y] as [number, number])\n).flat();",
    "Zig": "// No comprehension; use loops\nvar squares: [10]i32 = undefined;\nfor (0..10) |i| {\n    squares[i] = @intCast(i * i);\n}",
}


def get_expanded_v4_rosetta():
    """Return all v4 expanded handcrafted entries."""
    entries = []
    idx = 40000
    for concept, lang_codes in EXPANDED_V4.items():
        cn = concept.replace('_', ' ').title()
        for lang, code in lang_codes.items():
            idx += 1
            entries.append({
                "id": f"rosetta_v4_{idx}",
                "concept": concept,
                "concept_name": cn,
                "language": lang,
                "code": code,
                "category": "rosetta_stone",
                "has_code": True,
                "code_lines": len(code.split('\n')),
                "source": "handcrafted",
            })
    return entries
